select su.* from sys_user su where su.active = 1
and (su.username like concat('%', #{request.q}, '%') or su.display_name like concat('%', #{request.q}, '%'))
and not exists (select 1 from sys_user_role sur where sur.user_id = su.id and sur.role_id in
#{rid}
) and exists (select 1 from sys_user_role sur2 inner join sys_role sr2 on sr2.id = sur2.role_id where sur2.user_id = su.id and sr2.group_type in ('PLATFORM', 'SYSTEM') )
and exists (select 1 from sys_user_role sur inner join sys_role sr on sr.id = sur.role_id where sur.user_id = su.id and sr.group_type in ('PLATFORM', 'SYSTEM')
and sr.id in
#{rid}
)

